-- Client Portal: all visibility flags default closed to preserve existing data securely.
CREATE TYPE "ClientApprovalStatus" AS ENUM ('PENDING', 'APPROVED', 'DECLINED', 'CANCELLED');
CREATE TYPE "PortalActivityType" AS ENUM ('LOGIN', 'INVITATION_ACTIVATED', 'DOCUMENT_VIEWED', 'DOCUMENT_DOWNLOADED', 'APPROVAL_SUBMITTED', 'SIGNATURE_OPENED', 'INVOICE_VIEWED', 'PASSWORD_CHANGED');
ALTER TABLE "Project" ADD COLUMN "portalVisible" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "clientDescription" TEXT;
ALTER TABLE "ProjectMilestone" ADD COLUMN "portalVisible" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "clientDescription" TEXT;
ALTER TABLE "Rental" ADD COLUMN "portalVisible" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "Invoice" ADD COLUMN "portalPublished" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE "ClientPortalUser" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "clientId" TEXT NOT NULL, "clientContactId" TEXT, "email" TEXT NOT NULL, "passwordHash" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "sessionVersion" INTEGER NOT NULL DEFAULT 1, "lastLoginAt" TIMESTAMP(3), "invitedAt" TIMESTAMP(3), "activatedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ClientPortalUser_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ClientPortalSession" ("id" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "portalUserId" TEXT NOT NULL, "sessionVersion" INTEGER NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ClientPortalSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ClientPortalInvitation" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "clientId" TEXT NOT NULL, "clientContactId" TEXT NOT NULL, "portalUserId" TEXT NOT NULL, "invitedByUserId" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "usedAt" TIMESTAMP(3), "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ClientPortalInvitation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DocumentPortalShare" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "clientId" TEXT NOT NULL, "documentId" TEXT NOT NULL, "sharedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "withdrawnAt" TIMESTAMP(3), CONSTRAINT "DocumentPortalShare_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ClientApprovalRequest" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "clientId" TEXT NOT NULL, "projectId" TEXT, "documentId" TEXT, "title" TEXT NOT NULL, "description" TEXT, "status" "ClientApprovalStatus" NOT NULL DEFAULT 'PENDING', "requestedByUserId" TEXT NOT NULL, "requestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "dueAt" TIMESTAMP(3), "respondedAt" TIMESTAMP(3), "respondedByPortalUserId" TEXT, "responseComment" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ClientApprovalRequest_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PortalActivity" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "clientId" TEXT NOT NULL, "portalUserId" TEXT, "type" "PortalActivityType" NOT NULL, "subjectId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PortalActivity_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ClientPortalUser_clientContactId_key" ON "ClientPortalUser"("clientContactId"); CREATE UNIQUE INDEX "ClientPortalUser_organizationId_email_key" ON "ClientPortalUser"("organizationId", "email"); CREATE INDEX "ClientPortalUser_organizationId_clientId_active_idx" ON "ClientPortalUser"("organizationId", "clientId", "active");
CREATE UNIQUE INDEX "ClientPortalSession_tokenHash_key" ON "ClientPortalSession"("tokenHash"); CREATE INDEX "ClientPortalSession_portalUserId_idx" ON "ClientPortalSession"("portalUserId"); CREATE INDEX "ClientPortalSession_expiresAt_idx" ON "ClientPortalSession"("expiresAt");
CREATE UNIQUE INDEX "ClientPortalInvitation_tokenHash_key" ON "ClientPortalInvitation"("tokenHash"); CREATE INDEX "ClientPortalInvitation_organizationId_clientId_expiresAt_idx" ON "ClientPortalInvitation"("organizationId", "clientId", "expiresAt");
CREATE UNIQUE INDEX "DocumentPortalShare_clientId_documentId_key" ON "DocumentPortalShare"("clientId", "documentId"); CREATE INDEX "DocumentPortalShare_organizationId_clientId_withdrawnAt_idx" ON "DocumentPortalShare"("organizationId", "clientId", "withdrawnAt");
CREATE INDEX "ClientApprovalRequest_organizationId_clientId_status_idx" ON "ClientApprovalRequest"("organizationId", "clientId", "status"); CREATE INDEX "PortalActivity_organizationId_clientId_createdAt_idx" ON "PortalActivity"("organizationId", "clientId", "createdAt");
ALTER TABLE "ClientPortalUser" ADD CONSTRAINT "ClientPortalUser_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT, ADD CONSTRAINT "ClientPortalUser_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE CASCADE, ADD CONSTRAINT "ClientPortalUser_clientContactId_fkey" FOREIGN KEY ("clientContactId") REFERENCES "ClientContact"("id") ON DELETE SET NULL;
ALTER TABLE "ClientPortalSession" ADD CONSTRAINT "ClientPortalSession_portalUserId_fkey" FOREIGN KEY ("portalUserId") REFERENCES "ClientPortalUser"("id") ON DELETE CASCADE;
ALTER TABLE "ClientPortalInvitation" ADD CONSTRAINT "ClientPortalInvitation_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT, ADD CONSTRAINT "ClientPortalInvitation_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE CASCADE, ADD CONSTRAINT "ClientPortalInvitation_clientContactId_fkey" FOREIGN KEY ("clientContactId") REFERENCES "ClientContact"("id") ON DELETE CASCADE, ADD CONSTRAINT "ClientPortalInvitation_portalUserId_fkey" FOREIGN KEY ("portalUserId") REFERENCES "ClientPortalUser"("id") ON DELETE CASCADE, ADD CONSTRAINT "ClientPortalInvitation_invitedByUserId_fkey" FOREIGN KEY ("invitedByUserId") REFERENCES "User"("id") ON DELETE RESTRICT;
ALTER TABLE "DocumentPortalShare" ADD CONSTRAINT "DocumentPortalShare_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT, ADD CONSTRAINT "DocumentPortalShare_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE CASCADE, ADD CONSTRAINT "DocumentPortalShare_documentId_fkey" FOREIGN KEY ("documentId") REFERENCES "Document"("id") ON DELETE CASCADE;
ALTER TABLE "ClientApprovalRequest" ADD CONSTRAINT "ClientApprovalRequest_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT, ADD CONSTRAINT "ClientApprovalRequest_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE CASCADE, ADD CONSTRAINT "ClientApprovalRequest_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE SET NULL, ADD CONSTRAINT "ClientApprovalRequest_documentId_fkey" FOREIGN KEY ("documentId") REFERENCES "Document"("id") ON DELETE SET NULL, ADD CONSTRAINT "ClientApprovalRequest_requestedByUserId_fkey" FOREIGN KEY ("requestedByUserId") REFERENCES "User"("id") ON DELETE RESTRICT, ADD CONSTRAINT "ClientApprovalRequest_respondedByPortalUserId_fkey" FOREIGN KEY ("respondedByPortalUserId") REFERENCES "ClientPortalUser"("id") ON DELETE SET NULL;
ALTER TABLE "PortalActivity" ADD CONSTRAINT "PortalActivity_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT, ADD CONSTRAINT "PortalActivity_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE CASCADE, ADD CONSTRAINT "PortalActivity_portalUserId_fkey" FOREIGN KEY ("portalUserId") REFERENCES "ClientPortalUser"("id") ON DELETE SET NULL;
